// WF-03 Node 2: Phân tích và bóc tách Stack Trace lỗi từ Backend
try {
  const input = $input.first().json;
  const raw = input.body?.data || input.body || input.data || input;

  const statusCode = parseInt(raw.statusCode || 500, 10);
  const endpoint = String(raw.path || raw.endpoint || raw.url || '/api/unknown').trim();
  const method = String(raw.method || 'POST').toUpperCase();
  const errorMessage = String(raw.message || raw.error || 'Internal Server Error').substring(0, 300);
  const stackTrace = String(raw.stack || raw.stackTrace || '').substring(0, 1500);
  const userId = raw.userId || 'GUEST';
  const timestamp = raw.timestamp || new Date().toISOString();

  // Regex trích xuất file nguồn TypeScript/JavaScript và số dòng gây lỗi
  const fileMatch = stackTrace.match(/at\s+(?:.*?)\s+\((.*?):(\d+):(\d+)\)/i) || stackTrace.match(/at\s+(.*?):(\d+):(\d+)/i);
  const culpritFile = fileMatch ? fileMatch[1].split(/[\\/]/).pop() : 'UnknownModule.ts';
  const culpritLine = fileMatch ? fileMatch[2] : 'N/A';

  const isDatabaseError = errorMessage.includes('ER_') || errorMessage.includes('QueryFailedError') || errorMessage.includes('Connection lost') || errorMessage.includes('foreign key') || errorMessage.includes('Deadlock');

  return [{
    json: {
      statusCode,
      endpoint,
      method,
      errorMessage,
      culpritFile,
      culpritLine,
      stackTrace: stackTrace || errorMessage,
      userId,
      timestamp,
      isDatabaseError
    }
  }];
} catch (err) {
  throw new Error('[WF-03 Parse Error] Failed: ' + err.message);
}

// WF-03 Node 3: Chống bão cảnh báo (Deduplication Signature)
const item = $input.first().json;
const errorSignature = `${item.method}_${item.endpoint}_${item.culpritFile}_${item.culpritLine}`.replace(/[^a-zA-Z0-9_]/g, '');
const incidentRef = 'ERR-' + Date.now().toString(36).toUpperCase();
const shouldNotifyImmediately = item.statusCode >= 500;

return [{
  json: {
    ...item,
    errorSignature,
    incidentRef,
    shouldNotifyImmediately
  }
}];

// WF-03 Node 5: Gemini AI Root Cause Analysis (Hybrid AI Engine)
const item = $input.first().json;
const endpoint = item.endpoint || "/api/unknown";
const method = item.method || "POST";
const culpritFile = item.culpritFile || "UnknownModule.ts";
const culpritLine = item.culpritLine || "N/A";
const errorMessage = item.errorMessage || "Internal Server Error";
const stackTrace = item.stackTrace || errorMessage;
const isDbError = Boolean(item.isDatabaseError);

let rootCause = "";
let suggestedFix = "";
const severity = isDbError ? "DATABASE_CRITICAL" : "LOGIC_HIGH";
let aiEngineUsed = "SRE Diagnostic Rules Engine v2.4";

// 1. Gọi Google Gemini AI nếu có GEMINI_API_KEY
let geminiApiKey = ""; try { geminiApiKey = (typeof $env !== "undefined" && $env.GEMINI_API_KEY) ? $env.GEMINI_API_KEY : ""; } catch (e) { geminiApiKey = ""; }

if (geminiApiKey) {
  try {
    const prompt = `Bạn là Chuyên gia Gỡ lỗi Cấp cao (Senior Software Architect & SRE) của hệ thống Backend NestJS + TypeScript + MySQL.
Hãy phân tích lỗi hệ thống sau và trả về đúng định dạng JSON:
{
  "rootCause": "<nguyên nhân gốc rễ ngắn gọn trong 1-2 câu>",
  "suggestedFix": "<hướng dẫn sửa lỗi chi tiết, có kèm ví dụ code ngắn>"
}

Thông tin sự cố:
- Endpoint: ${method} ${endpoint}
- Tệp tin nghi vấn: ${culpritFile} (Dòng: ${culpritLine})
- Thông báo lỗi: ${errorMessage}
- Stack Trace: ${stackTrace.substring(0, 500)}`;

    const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${geminiApiKey}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: { temperature: 0.1, responseMimeType: "application/json" }
      })
    });

    if (response.ok) {
      const resData = await response.json();
      const text = resData.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || "";
      try {
        const parsed = JSON.parse(text);
        rootCause = parsed.rootCause || "";
        suggestedFix = parsed.suggestedFix || "";
        if (rootCause) {
          aiEngineUsed = "Google Gemini 2.5 Flash";
        }
      } catch (e) {
        rootCause = text;
      }
    }
  } catch (apiErr) {
    // Tự động chuyển tiếp fallback nếu offline
  }
}

// 2. Fallback chẩn đoán chuyên sâu theo mẫu lỗi SRE chuẩn
if (!rootCause) {
  if (isDbError) {
    rootCause = `Xung đột ràng buộc dữ liệu quan hệ (Foreign Key Constraint), vi phạm trùng lặp khóa duy nhất (ER_DUP_ENTRY) hoặc cạn kiệt Connection Pool tại cơ sở dữ liệu.`;
    suggestedFix = `1. Kiểm tra lại dữ liệu khóa ngoại trước khi gọi repository.save(). 2. Bọc nghiệp vụ nhiều bước vào TypeORM DataSource QueryRunner (Transaction). 3. Tăng tham số connectionLimit trong cấu hình MySQL pool.`;
  } else if (errorMessage.includes("Cannot read properties of") || errorMessage.includes("is not defined") || errorMessage.includes("null")) {
    rootCause = `Ngoại lệ NullPointerException do truy xuất thuộc tính của biến chưa khởi tạo (undefined/null) tại tệp ${culpritFile}:${culpritLine}.`;
    suggestedFix = `Sử dụng toán tử an toàn Optional Chaining (?.) hoặc kiểm tra kỹ đầu vào DTO với class-validator (@IsNotEmpty(), @IsOptional()) trước khi xử lý.`;
  } else {
    rootCause = `Ngoại lệ thời gian chạy (Runtime Exception) chưa được xử lý trong luồng bất đồng bộ (Promise rejection) tại endpoint ${method} ${endpoint}.`;
    suggestedFix = `Bổ sung khối try/catch bắt ngoại lệ cục bộ, rà soát lại các hàm async/await và kiểm tra danh sách Provider trong NestJS Module tương ứng.`;
  }
}

return [{
  json: {
    ...item,
    aiDiagnostic: {
      rootCause,
      suggestedFix,
      severity
    },
    aiEngine: aiEngineUsed
  }
}];

// WF-03 Node 6: Định dạng Playbook khắc phục sự cố
const item = $input.first().json;
const formattedPlaybook = `
🔥 [SỰ CỐ HỆ THỐNG CẦN XỬ LÝ]: ${item.incidentRef}
• API Endpoint: ${item.method} ${item.endpoint}
• Vị trí nghi vấn: File ${item.culpritFile} (Dòng ${item.culpritLine})
• Thông báo lỗi: ${item.errorMessage}
• Chẩn đoán AI: ${item.aiDiagnostic.rootCause}
• Hướng dẫn khắc phục: ${item.aiDiagnostic.suggestedFix}
`;

return [{
  json: {
    ...item,
    formattedPlaybook
  }
}];

